import React, { ElementType } from 'react';
import { HeadingProps } from './HeadingTypes';
import { Text } from './Heading.styles';

const defineComponent = (value: string): ElementType => {
  switch (value) {
    case 'H2':
      return 'h2';
    case 'H3':
      return 'h3';
    case 'H4':
      return 'h4';
    case 'H5':
      return 'h5';
    default:
      return 'h1';
  }
};

const Heading = React.forwardRef(
  (
    {
      size = 'H1',
      foreground = 'false',
      alignment = 'left',
      selectable = 'true',
      children,
      css,
      ...props
    }: Omit<HeadingProps, 'as'>,
    forwardedRef: React.ForwardedRef<HTMLHeadingElement>
  ): JSX.Element => (
    <Text
      as={defineComponent(size)}
      size={size}
      foreground={foreground}
      alignment={alignment}
      selectable={selectable}
      ref={forwardedRef}
      css={css}
      {...props}
    >
      {children}
    </Text>
  )
);

export default Heading;
